#!/usr/bin/env python3
from pwn import *
import hashlib

def hash_pair(left, right):
    combined = bytes.fromhex(left) + bytes.fromhex(right)
    return hashlib.sha256(combined).hexdigest()

def build_merkle_tree(leaves):
    if len(leaves) == 1:
        return leaves[0]

    new_leaves = []
    for i in range(0, len(leaves), 2):
        if i + 1 < len(leaves):
            new_leaves.append(hash_pair(leaves[i], leaves[i+1]))
        else:
            new_leaves.append(leaves[i])

    return build_merkle_tree(new_leaves)

def test_merkle_combinations():
    # Connect to the server
    conn = remote('misc.chal.csaw.io', 1337)

    try:
        # Receive initial banner
        print(conn.recvuntil(b'Input: ', timeout=2).decode())

        # Test some basic leaves
        leaf_combinations = [
            ["00"*32, "11"*32],
            ["dead"*16, "beef"*16],
            ["face"*16, "feed"*16],
            [hashlib.sha256(b"urkel").hexdigest(), hashlib.sha256(b"tree").hexdigest()],
            [hashlib.sha256(b"merkle").hexdigest(), hashlib.sha256(b"root").hexdigest()]
        ]

        for leaves in leaf_combinations:
            # Try both orderings of leaves
            root1 = build_merkle_tree(leaves)
            root2 = build_merkle_tree(leaves[::-1])  # reversed order

            # Try different formats
            test_values = [
                root1,
                root2,
                "0x" + root1,
                "0x" + root2,
                root1.upper(),
                root2.upper()
            ]

            for value in test_values:
                print(f"\nTrying value: {value}")
                conn.sendline(value.encode())
                try:
                    response = conn.recvuntil(b'Input: ', timeout=2).decode()
                    print("Server response:", response)

                    if 'csawctf{' in response:
                        print("Found flag!")
                        return response
                except EOFError:
                    print("Connection closed by server")
                    conn = remote('misc.chal.csaw.io', 1337)
                    print(conn.recvuntil(b'Input: ', timeout=2).decode())

    except Exception as e:
        print(f"Error: {e}")
    finally:
        conn.close()

if __name__ == '__main__':
    result = test_merkle_combinations()
    print("Final result:", result)
